(* [comment removed for export] *)
Definition rmrep_W (st : mstate) : list (Z * Z) :=
  (RCTX, RCTX + 928)
  :: map (fun kr : N * region => (r_base (snd kr), r_base (snd kr) + round_up_pg (r_len (snd kr)))) (map_to_list (s_regions st)).

